mapper.select:
SELECT
SUM(cost) as total_cost,
COUNT(*) as total_calls,
SUM(total_tokens) as total_tokens
FROM model_usage_cost
WHERE user_id = #{userId}
AND created_at >= #{startDate}
AND created_at <= #{endDate}

SELECT
am.model_name as model_name,
SUM(muc.cost) as cost,
SUM(muc.total_tokens) as tokens
FROM model_usage_cost muc
LEFT JOIN ai_model am ON muc.model_id = am.id
WHERE muc.user_id = #{userId}
AND muc.created_at >= #{startDate}
AND muc.created_at <= #{endDate}
GROUP BY am.model_name

SELECT
a.name as agent_name,
COUNT(*) as calls
FROM model_usage_cost muc
LEFT JOIN agent a ON muc.agent_id = a.id
WHERE muc.user_id = #{userId}
AND muc.created_at >= #{startDate}
AND muc.created_at <= #{endDate}
GROUP BY a.name

SELECT
SUM(cost) as total_cost,
COUNT(*) as total_calls,
SUM(total_tokens) as total_tokens
FROM model_usage_cost
WHERE agent_id = #{agentId}
AND created_at >= #{startDate}
AND created_at <= #{endDate}
